demand = {"수신": 300, "여신": 300, "카드": 300}   # 초당 요청
hold = {"수신": 0.02, "여신": 0.02, "카드": 1.0}    # 요청 하나가 연결을 잡는 시간(초) — 카드 쪽이 느려졌다

def shared(cap):                       # 연결을 같이 쓴다: 느린 요청이 먼저 다 잡는 최악의 경우
    slow_takes = min(cap, demand["카드"] * hold["카드"])
    left = cap - slow_takes
    return {d: round(slow_takes / hold[d]) if d == "카드" else round(min(demand[d], left / 2 / hold[d]))
            for d in demand}

def split(per):                        # 도메인마다 연결을 따로(벌크헤드)
    return {d: round(min(demand[d], per / hold[d])) for d in demand}

print("연결 60개를 같이 쓸 때  :", shared(60))
print("도메인마다 20개씩 나눌 때:", split(20))

rendered = {                      # 템플릿에서 다시 그린 파이프라인의 단계들
    "svc-a": ["build", "test", "approve", "deploy"],
    "svc-b": ["build", "deploy"],
    "svc-c": ["build", "test", "deploy", "approve"],
}
for name, stages in rendered.items():
    if "approve" not in stages:
        print(name, "→ 막음: 승인 단계 없음")
    elif stages.index("approve") > stages.index("deploy"):
        print(name, "→ 막음: 승인이 배포보다 뒤")
    else:
        print(name, "→ 통과")

def should_rollback(errors_per_min, threshold, last_log_age_s, lag_limit_s):
    if errors_per_min > threshold:
        return "롤백: 오류 로그 %d건 > 기준 %d" % (errors_per_min, threshold)
    if last_log_age_s > lag_limit_s:
        return "롤백: 로그가 %d초째 안 들어옴(감시가 눈먼 상태)" % last_log_age_s
    return "계속"

print(should_rollback(12, 50, 5, 60))
print(should_rollback(80, 50, 5, 60))
print(should_rollback(3, 50, 180, 60))
